import assert from 'assert'
import math from './src/defaultInstance.js'
const isInteger = math.isInteger
const bignumber = math.bignumber
const fraction = math.fraction
const __numagentCases = [["isInteger((0.2 + 0.1) * 10)", "isInteger((0.2 + 0.1) * 10)", [], "true"], ["isInteger((0.1 + 0.2) * 10)", "isInteger((0.1 + 0.2) * 10)", [], "true"], ["isInteger((0.1 + 0.2) * 10 - 3)", "isInteger((0.1 + 0.2) * 10 - 3)", [], "true"], ["isInteger(0.1 + 0.2)", "isInteger(0.1 + 0.2)", [], "false"]];
for (const [__name, __expr, __binds, __want] of __numagentCases) {
  try {
    for (const __b of __binds) { eval("var " + __b); }
    probe(__name, eval(__expr));
  } catch (e) {
    probe(__name, "__error__: " + ((e && e.name) ? e.name : "Error") + ": " +
          String((e && e.message) ? e.message : e).slice(0, 200));
  }
  if (__want) {
    try { probe("expected::" + __name, eval(__want)); } catch (e) { }
  }
}

buggy.isinteger_roundoff_cases:
import math from 'mathjs';

function toBool(x){return Boolean(x);}

const a = 0.1 + 0.2;
const x = a * 10;
const y = x - 3;

const cases = [
  {name: 'case_isInteger((0.2+0.1)*10)', expr: (math.isInteger((0.2+0.1)*10)), val: (0.2+0.1)*10},
  {name: 'case_isInteger((0.1+0.2)*10)', expr: (math.isInteger(x)), val: x},
  {name: 'case_isInteger((0.1+0.2)*10-3)', expr: (math.isInteger(y)), val: y},
  {name: 'case_isInteger(0.1+0.2)', expr: (math.isInteger(a)), val: a},
  {name: 'case_isInteger(bignumber((0.1+0.2)*10))', expr: (math.isInteger(math.bignumber(x))), val: x},
  {name: 'case_isInteger(bignumber((0.1+0.2)*10-3))', expr: (math.isInteger(math.bignumber(y))), val: y},
];

for (const c of cases) {
  probe(c.name, toBool(c.expr));
  probe(c.name + '.value', c.val);
}

